#include <iostream>
#include <vector>

int partition(std::vector<int>& a, int lo, int hi) {
    int pivot = a[hi];
    int i = lo;

    for (int j = lo; j < hi; j++) {
        if (a[j] < pivot) {
            std::swap(a[i], a[j]);
            i++;
        }
    }

    std::swap(a[i], a[hi]);
    return i;
}

void quick(std::vector<int>& a, int lo, int hi) {
    if (lo >= hi) {
        return;
    }
    int p = partition(a, lo, hi);
    quick(a, lo, p - 1);
    quick(a, p + 1, hi);
}

int main() {
    std::vector<int> a = {{p1}, {p2}, {p3}, {p4}, {p5}};
    quick(a, 0, 4);

    std::cout << "尺子法：";
    for (int i = 0; i < 5; i++) {
        std::cout << a[i] << " ";
    }
    std::cout << "\n";
    return 0;
}
